content:
* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
  font-family: 'Courier New', Courier, monospace, sans-serif;
}

body {
  background-color: #121212;
  color: #e0e0e0;
  display: flex;
  justify-content: center;
  align-items: center;
  min-height: 100vh;
  overflow: hidden;
}

.app-container {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  background-color: #1e1e1e;
  padding: 20px;
  border-radius: 12px;
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.5);
  max-width: 400px;
  width: 100%;
  border: 2px solid #333;
}

.header {
  text-align: center;
  margin-bottom: 15px;
  width: 100%;
}

.title {
  font-size: 24px;
  font-weight: bold;
  color: #4caf50;
  margin-bottom: 8px;
  letter-spacing: 2px;
  text-transform: uppercase;
}

.score-board {
  display: flex;
  justify-content: space-around;
  font-size: 14px;
  color: #b0b0b0;
  background-color: #2a2a2a;
  padding: 8px 12px;
  border-radius: 6px;
  border: 1px solid #444;
}

.score-board span {
  font-weight: bold;
  color: #fff;
}

.game-board {
  position: relative;
  display: grid;
  grid-template-columns: repeat(20, 1fr);
  grid-template-rows: repeat(20, 1fr);
  width: 320px;
  height: 320px;
  background-color: #000;
  border: 4px solid #333;
  border-radius: 4px;
  overflow: hidden;
}

.cell {
  width: 100%;
  height: 100%;
}

.cell.snake-head {
  background-color: #4caf50;
  border-radius: 2px;
}

.cell.snake-body {
  background-color: #81c784;
  border-radius: 2px;
}

.cell.food {
  background-color: #e53935;
  border-radius: 50%;
  box-shadow: 0 0 6px #e53935;
}

.game-over-overlay {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background-color: rgba(0, 0, 0, 0.85);
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  z-index: 10;
  animation: fadeIn 0.2s ease-in-out;
}

.game-over-overlay h2 {
  color: #e53935;
  font-size: 26px;
  margin-bottom: 10px;
  text-transform: uppercase;
  letter-spacing: 1px;
}

.game-over-overlay p {
  color: #fff;
  font-size: 16px;
  margin-bottom: 20px;
}

.btn {
  background-color: #444;
  color: #fff;
  border: none;
  padding: 10px 20px;
  font-size: 14px;
  font-weight: bold;
  border-radius: 6px;
  cursor: pointer;
  transition: background-color 0.2s, transform 0.1s;
  text-transform: uppercase;
  letter-spacing: 1px;
  user-select: none;
}

.btn:active {
  transform: scale(0.95);
}

.btn:focus-visible,
.control-btn:focus-visible {
  outline: 2px solid #4caf50;
  outline-offset: 2px;
}

.btn-primary {
  background-color: #4caf50;
  color: #fff;
}

.btn-primary:hover {
  background-color: #43a047;
}

.controls {
  margin-top: 20px;
  display: flex;
  flex-direction: column;
  align-items: center;
  width: 100%;
}

.d-pad {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 6px;
}

.d-pad-row {
  display: flex;
  gap: 6px;
}

.d-pad-spacer {
  width: 50px;
  height: 50px;
}

.control-btn {
  width: 50px;
  height: 50px;
  background-color: #2a2a2a;
  color: #fff;
  border: 1px solid #444;
  border-radius: 8px;
  font-size: 20px;
  display: flex;
  justify-content: center;
  align-items: center;
  cursor: pointer;
  box-shadow: 0 4px 6px rgba(0, 0, 0, 0.3);
  transition: background-color 0.1s, transform 0.1s;
  user-select: none;
}

.control-btn:active {
  background-color: #383838;
  transform: translateY(2px);
  box-shadow: 0 2px 3px rgba(0, 0, 0, 0.3);
}

@keyframes fadeIn {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}

@media (max-width: 400px) {
  body {
    align-items: flex-start;
    padding-top: 10px;
  }

  .app-container {
    padding: 12px;
    max-width: 100%;
    border-radius: 8px;
  }

  .game-board {
    width: 280px;
    height: 280px;
  }

  .control-btn {
    width: 44px;
    height: 44px;
    font-size: 18px;
  }

  .d-pad-spacer {
    width: 44px;
    height: 44px;
  }
}

/**
 * 2次元座標上の位置を表す型
 */
export type Point = {
  /** X座標 */
  x: number;
  /** Y座標 */
  y: number;
};

/**
 * スネークの移動方向
 */
export type Direction = 'UP' | 'DOWN' | 'LEFT' | 'RIGHT';

/**
 * ゲームの現在の状態
 */
export type GameState = 'PLAYING' | 'GAME_OVER' | 'PAUSED';

/**
 * ゲームの難易度や操作設定を表す型（将来の拡張用）
 */
export type GameSettings = {
  speed: number;
  gridSize: number;
  soundEnabled: boolean;
};

/**
 * プレイ履歴やハイスコアの記録を表す型（将来の拡張用）
 */
export type ScoreRecord = {
  score: number;
  achievedAt: string;
};

import { useState, useEffect, useCallback, useRef } from 'react';
import { Point, Direction, GameState } from './types';
import './index.css';

const GRID_SIZE = 20;
const INITIAL_SNAKE: Point[] = [
  { x: 10, y: 10 },
  { x: 10, y: 11 },
  { x: 10, y: 12 },
];
const INITIAL_DIRECTION: Direction = 'UP';
const INITIAL_SPEED = 120;

export default function App() {
  const [snake, setSnake] = useState<Point[]>(INITIAL_SNAKE);
  const [direction, setDirection] = useState<Direction>(INITIAL_DIRECTION);
  const [food, setFood] = useState<Point>({ x: 5, y: 5 });
  const [gameState, setGameState] = useState<GameState>('PLAYING');
  const [score, setScore] = useState<number>(0);
  const [highScore, setHighScore] = useState<number>(() => {
    const saved = localStorage.getItem('snake_high_score');
    return saved ? parseInt(saved, 10) : 0;
  });

  const directionRef = useRef(direction);
  directionRef.current = direction;

  const foodRef = useRef(food);
  foodRef.current = food;

  const scoreRef = useRef(score);
  scoreRef.current = score;

  const highScoreRef = useRef(highScore);
  highScoreRef.current = highScore;

  const generateFood = useCallback((currentSnake: Point[]): Point => {
    let newFood: Point;
    while (true) {
      newFood = {
        x: Math.floor(Math.random() * GRID_SIZE),
        y: Math.floor(Math.random() * GRID_SIZE),
      };
      const isOnSnake = currentSnake.some(
        (segment) => segment.x === newFood.x && segment.y === newFood.y
      );
      if (!isOnSnake) break;
    }
    return newFood;
  }, []);

  const resetGame = () => {
    const newSnake = INITIAL_SNAKE;
    setSnake(newSnake);
    setDirection(INITIAL_DIRECTION);
    directionRef.current = INITIAL_DIRECTION;
    const newFood = generateFood(newSnake);
    setFood(newFood);
    foodRef.current = newFood;
    setScore(0);
    scoreRef.current = 0;
    setGameState('PLAYING');
  };

  const togglePause = () => {
    setGameState((prev) => {
      if (prev === 'PLAYING') return 'PAUSED';
      if (prev === 'PAUSED') return 'PLAYING';
      return prev;
    });
  };

  const changeDirection = useCallback((newDir: Direction) => {
    const current = directionRef.current;
    if (
      (newDir === 'UP' && current !== 'DOWN') ||
      (newDir === 'DOWN' && current !== 'UP') ||
      (newDir === 'LEFT' && current !== 'RIGHT') ||
      (newDir === 'RIGHT' && current !== 'LEFT')
    ) {
      setDirection(newDir);
      directionRef.current = newDir;
    }
  }, []);

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key === ' ' || e.key === 'p' || e.key === 'P') {
        e.preventDefault();
        setGameState((prev) => {
          if (prev === 'PLAYING') return 'PAUSED';
          if (prev === 'PAUSED') return 'PLAYING';
          return prev;
        });
        return;
      }

      switch (e.key) {
        case 'ArrowUp':
        case 'w':
        case 'W':
          e.preventDefault();
          changeDirection('UP');
          break;
        case 'ArrowDown':
        case 's':
        case 'S':
          e.preventDefault();
          changeDirection('DOWN');
          break;
        case 'ArrowLeft':
        case 'a':
        case 'A':
          e.preventDefault();
          changeDirection('LEFT');
          break;
        case 'ArrowRight':
        case 'd':
        case 'D':
          e.preventDefault();
          changeDirection('RIGHT');
          break;
        default:
          break;
      }
    };

    window.addEventListener('keydown', handleKeyDown);
    return () => {
      window.removeEventListener('keydown', handleKeyDown);
    };
  }, [changeDirection]);

  // スコア上昇に伴うスピードアップ調整
  const currentSpeed = Math.max(40, INITIAL_SPEED - Math.floor(score / 50) * 15);

  useEffect(() => {
    if (gameState !== 'PLAYING') return;

    const moveSnake = () => {
      setSnake((prevSnake) => {
        const head = { ...prevSnake[0] };

        switch (directionRef.current) {
          case 'UP':
            head.y -= 1;
            break;
          case 'DOWN':
            head.y += 1;
            break;
          case 'LEFT':
            head.x -= 1;
            break;
          case 'RIGHT':
            head.x += 1;
            break;
        }

        // 壁との衝突判定
        if (
          head.x < 0 ||
          head.x >= GRID_SIZE ||
          head.y < 0 ||
          head.y >= GRID_SIZE
        ) {
          setGameState('GAME_OVER');
          return prevSnake;
        }

        // 自分との衝突判定
        for (const segment of prevSnake) {
          if (segment.x === head.x && segment.y === head.y) {
            setGameState('GAME_OVER');
            return prevSnake;
          }
        }

        const newSnake = [head, ...prevSnake];

        // エサを食べた判定
        const currentFood = foodRef.current;
        if (head.x === currentFood.x && head.y === currentFood.y) {
          const newScore = scoreRef.current + 10;
          setScore(newScore);
          scoreRef.current = newScore;
          if (newScore > highScoreRef.current) {
            setHighScore(newScore);
            highScoreRef.current = newScore;
            localStorage.setItem('snake_high_score', newScore.toString());
          }
          const nextFood = generateFood(newSnake);
          setFood(nextFood);
          foodRef.current = nextFood;
        } else {
          newSnake.pop();
        }

        return newSnake;
      });
    };

    const intervalId = setInterval(moveSnake, currentSpeed);
    return () => clearInterval(intervalId);
  }, [gameState, currentSpeed, generateFood]);

  const renderCells = () => {
    const cells = [];
    for (let y = 0; y < GRID_SIZE; y++) {
      for (let x = 0; x < GRID_SIZE; x++) {
        const isHead = snake[0].x === x && snake[0].y === y;
        const isBody = snake.slice(1).some((segment) => segment.x === x && segment.y === y);
        const isFood = food.x === x && food.y === y;

        let className = 'cell';
        if (isHead) className += ' snake-head';
        else if (isBody) className += ' snake-body';
        else if (isFood) className += ' food';

        cells.push(<div key={`${x}-${y}`} className={className} />);
      }
    }
    return cells;
  };

  return (
    <div className="app-container">
      <header className="header">
        <h1 className="title">スネークゲーム</h1>
        <div className="score-board">
          <div>スコア: <span>{score}</span></div>
          <div>ハイスコア: <span>{highScore}</span></div>
          <button 
            className="btn" 
            onClick={togglePause} 
            style={{ padding: '2px 8px', fontSize: '12px', marginLeft: '10px' }}
          >
            {gameState === 'PAUSED' ? '再開' : '一時停止'}
          </button>
        </div>
      </header>

      <div className="game-board">
        {renderCells()}
        {gameState === 'PAUSED' && (
          <div className="game-over-overlay">
            <h2>一時停止中</h2>
            <button className="btn btn-primary" onClick={togglePause}>
              ゲームに戻る
            </button>
          </div>
        )}
        {gameState === 'GAME_OVER' && (
          <div className="game-over-overlay">
            <h2>ゲームオーバー</h2>
            <p>スコア: {score}</p>
            <button className="btn btn-primary" onClick={resetGame}>
              もう一度プレイ
            </button>
          </div>
        )}
      </div>

      <div className="controls">
        <div className="d-pad">
          <div className="d-pad-row">
            <div className="d-pad-spacer" />
            <button
              className="control-btn"
              onClick={() => changeDirection('UP')}
              aria-label="上"
            >
              ▲
            </button>
            <div className="d-pad-spacer" />
          </div>
          <div className="d-pad-row">
            <button
              className="control-btn"
              onClick={() => changeDirection('LEFT')}
              aria-label="左"
            >
              ◀
            </button>
            <div className="d-pad-spacer" />
            <button
              className="control-btn"
              onClick={() => changeDirection('RIGHT')}
              aria-label="右"
            >
              ▶
            </button>
          </div>
          <div className="d-pad-row">
            <div className="d-pad-spacer" />
            <button
              className="control-btn"
              onClick={() => changeDirection('DOWN')}
              aria-label="下"
            >
              ▼
            </button>
            <div className="d-pad-spacer" />
          </div>
        </div>
      </div>
    </div>
  );
}
